78	                    | Expr::BooleanLiteral(_)
79	                    | Expr::NoneLiteral(_)
80	                    | Expr::EllipsisLiteral(_)
81	                    | Expr::FString(_)
82	                    | Expr::List(_)
83	                    | Expr::Tuple(_)
84	                    | Expr::Set(_)
85	                    | Expr::Dict(_)
86	                    | Expr::ListComp(_)
87	                    | Expr::SetComp(_)
88	                    | Expr::DictComp(_)
89	            ) {
90	                return true;
91	            }
92	            if !matches!(
93	                right.as_ref(),
94	                Expr::StringLiteral(_)
95	                    | Expr::BytesLiteral(_)
96	                    | Expr::NumberLiteral(_)
97	                    | Expr::BooleanLiteral(_)
98	                    | Expr::NoneLiteral(_)
99	                    | Expr::EllipsisLiteral(_)
100	                    | Expr::FString(_)
101	                    | Expr::List(_)
102	                    | Expr::Tuple(_)
103	                    | Expr::Set(_)
